class Probe extends Capturing {
 static styles=css`#content{padding:24px;padding-inline:4px}`;
 applications=0;
 applyInputs(values){this.applications++;for(const key of ["padding","paddingInline"])this[key]=values[key];this.declarationOrder=Object.keys(values).filter(k=>values[k]!==undefined);}
}
class Inputs extends AsyncDirective {
 constructor(info){super(info);if(info.type!==PartType.ELEMENT)throw Error("Element expression required");}
 element;values={};generation=0;
 render(){return noChange;}
 update(part,[values]){this.element=part.element;this.values={...values};this.schedule(true);return noChange;}
 schedule(explicitUpdate=false){
  const generation=++this.generation;
  const registry=this.element.ownerDocument.defaultView.customElements;
  if(registry.get(this.element.localName)){if(explicitUpdate||this.isConnected)this.apply(generation,explicitUpdate);return;}
  if(!this.isConnected)return;
  const weak=new WeakRef(this);
  registry.whenDefined(this.element.localName).then(()=>weak.deref()?.apply(generation,false));
 }
 apply(generation,explicitUpdate){
  if(generation!==this.generation||(!explicitUpdate&&!this.isConnected))return;
  const registry=this.element.ownerDocument.defaultView.customElements;registry.upgrade(this.element);
  this.element.applyInputs(this.values);
 }
 disconnected(){this.generation++;}
 reconnected(){this.schedule();}
}
